package com.jnapanam.sportszone.admin.controller;import com.jnapanam.sportszone.admin.dto.*;import com.jnapanam.sportszone.admin.service.AdminReportingService;import java.time.LocalDate;import java.util.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public class AdminReportingController{private final AdminReportingService service;public AdminReportingController(AdminReportingService s){service=s;}@GetMapping("/dashboard")public DashboardResponse dashboard(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return service.dashboard(from,to);}@GetMapping("/reconciliation")public ReconciliationResponse reconciliation(){return service.reconciliation();}@GetMapping("/reports/revenue")public List<Map<String,Object>>revenue(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return service.revenue(from,to);}@GetMapping("/reports/bookings")public List<Map<String,Object>>bookings(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return service.bookings(from,to);}@GetMapping("/reports/memberships")public List<Map<String,Object>>memberships(){return service.memberships();}@GetMapping("/audit-logs")public List<AuditLogResponse>audit(@RequestParam(defaultValue="100")int limit){return service.audit(limit);}}
